Definition H9 (R : bvmap 5 word) (M : word -> option byte) (model : Model) (cr : credit) (be : bool) : Prop :=
  (exists Rm, PECHU.hcore L R0 M0 model0 sp ra LB0 Rm M model)
  /\ getr R (reg 1) = Z_to_bv 64 ra /\ getr R (reg 2) = Z_to_bv 64 sp /\ getr R (reg 8) = getr R0 (reg 8) /\ getr R (reg 9) = getr R0 (reg 9) /\ getr R (reg 10) = Z_to_bv 64 0
  /\ (forall k, In k CSK -> getr R (reg k) = getr R0 (reg k))
  /\ PECHU.hstat M true true be /\ (PMST.st_err g = true -> be = true)
  /\ hi_heap HI LB0 cr M (m_vmmaps model)
  /\ PMSP.credit_keep cr0 cr (PECHU.P0 L P payload) PMSP.cr0.

Lemma s_gone :
  PMSP.opdel_spec RSEGS AD L HI ->
  forall (fx : FPState) R M model cr s be K,
    PECHU.H7 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R M model cr s be -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        H9 R1 M1 model1 cr be ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x350bc M1 model1) K) ->
